use crate::{cli::Algorithm,hashing::hash_file};use serde::Serialize;use std::{fs,path::{Path,PathBuf}};use walkdir::WalkDir;
#[derive(Serialize,serde::Deserialize,Clone)]pub struct FileRecord{pub path:String,pub size:u64,pub hash:Option<String>}
pub fn files(root:&Path,hidden:bool,ignore:&[String],algorithm:Option<Algorithm>)->Result<Vec<FileRecord>,String>{if !root.is_dir(){return Err(format!("{} is not a directory",root.display()))}let mut out=Vec::new();for e in WalkDir::new(root).follow_links(false).into_iter().filter_map(Result::ok){if !e.file_type().is_file(){continue}let p=e.path();let relative=p.strip_prefix(root).unwrap_or(p);let name=relative.to_string_lossy();if(!hidden&&relative.components().any(|c|c.as_os_str().to_string_lossy().starts_with('.')))||ignore.iter().any(|x|name.contains(x.trim_matches('*'))){continue}let size=fs::metadata(p).map_err(|e|e.to_string())?.len();let hash=match algorithm{Some(a)=>Some(hash_file(p,a).map_err(|e|format!("{}: {e}",p.display()))?),None=>None};out.push(FileRecord{path:name.replace('\\',"/"),size,hash})}Ok(out)}
pub fn full(root:&Path,record:&FileRecord)->PathBuf{root.join(&record.path)}
